changeSet.sql:
CREATE OR REPLACE FUNCTION llm_model_gets_own_call_pool() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.call_pool_id IS NULL THEN
        INSERT INTO llm_call_pool (slug, display_name, dedicated, created_at, updated_at)
        VALUES (TG_ARGV[0] || NEW.id, 'Own capacity of ' || TG_ARGV[0] || NEW.id, TRUE, now(), now())
        RETURNING id INTO NEW.call_pool_id;
    END IF;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION llm_model_ends_own_call_pool() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'UPDATE' AND NEW.call_pool_id IS NOT DISTINCT FROM OLD.call_pool_id THEN
        RETURN NULL;
    END IF;
    -- The pool row first, as admission locks it before it writes a permit.
    PERFORM 1 FROM llm_call_pool WHERE id = OLD.call_pool_id AND dedicated FOR UPDATE;
    IF FOUND THEN
        DELETE FROM llm_call_permit WHERE pool_id = OLD.call_pool_id;
        DELETE FROM llm_call_pool WHERE id = OLD.call_pool_id;
    END IF;
    RETURN NULL;
END;
$$;

CREATE OR REPLACE TRIGGER llm_model_own_call_pool BEFORE INSERT OR UPDATE OF call_pool_id ON llm_model
    FOR EACH ROW EXECUTE FUNCTION llm_model_gets_own_call_pool('own-model-');
CREATE OR REPLACE TRIGGER llm_model_end_own_call_pool AFTER UPDATE OF call_pool_id OR DELETE ON llm_model
    FOR EACH ROW EXECUTE FUNCTION llm_model_ends_own_call_pool();
CREATE OR REPLACE TRIGGER workspace_llm_model_own_call_pool BEFORE INSERT OR UPDATE OF call_pool_id ON workspace_llm_model
    FOR EACH ROW EXECUTE FUNCTION llm_model_gets_own_call_pool('own-workspace-model-');
CREATE OR REPLACE TRIGGER workspace_llm_model_end_own_call_pool AFTER UPDATE OF call_pool_id OR DELETE ON workspace_llm_model
    FOR EACH ROW EXECUTE FUNCTION llm_model_ends_own_call_pool();

UPDATE llm_model SET call_pool_id = NULL WHERE call_pool_id IS NULL;
UPDATE workspace_llm_model SET call_pool_id = NULL WHERE call_pool_id IS NULL;

rollback.sql:
DROP TRIGGER workspace_llm_model_end_own_call_pool ON workspace_llm_model;
DROP TRIGGER workspace_llm_model_own_call_pool ON workspace_llm_model;
DROP TRIGGER llm_model_end_own_call_pool ON llm_model;
DROP TRIGGER llm_model_own_call_pool ON llm_model;
DROP FUNCTION llm_model_ends_own_call_pool();
DROP FUNCTION llm_model_gets_own_call_pool();
DELETE FROM llm_call_permit WHERE pool_id IN (SELECT id FROM llm_call_pool WHERE dedicated);
DELETE FROM llm_call_pool WHERE dedicated;
